from pathlib import Path
import json
P=Path(__file__).resolve().parent;e=json.loads((P/'edits.json').read_text());n=json.loads((P/'notes.json').read_text())
def p(k,t):e[f'A0554-B{k:04d}']=t
p(2,'荷鲁斯之子原名影月苍狼，是最初二十个星际战士军团中的第十六军团。其原体荷鲁斯，被军团成员称为荷鲁斯·卢佩卡尔；在帝国史上，他因发动帝国第一次大规模内战——荷鲁斯之乱——而闻名。叛乱结束后，大多数荷鲁斯之子逃入恐惧之眼，又在随后的军团战争中遭到重创。和谐星之战后，大批残部被前第一连长以泽凯尔·阿巴顿组建的黑色军团吸收。少数后来被称为“三重诅咒叛徒”的战帮，则保持独立，至今仍以荷鲁斯之子的名义活动。')
p(16,'专长：灵活编组、摧毁敌方指挥体系、行星突击')
p(18,'战吼：“卢佩卡尔！”“为了战帅！”')
p(21,'相传，影月苍狼起源于科索尼亚。这颗行星据说位于距离泰拉最近的邻近星系之一，即使不用亚空间航行也能抵达。因此，很可能从人类开始太空旅行之初，这里就已遭到殖民开发，人们营建城市、开凿地道、采掘矿藏。早在荷鲁斯·卢佩卡尔到来前数千年，自然资源便已枯竭；古老采矿技术也早被火星的技术人员重新发现并带走。残存的世界失去用途，几乎被彻底遗弃，只剩遍布全球的地下洞窟、摇摇欲坠的工业设施与废弃矿井。帝国现存记录称科索尼亚已不复存在，据信它在荷鲁斯之乱后数百年间发生灾难性的地质结构崩溃。许多人将其归咎于过度开采——坑道一直深入到死寂的地核——但也有大量猜测认为，是身份不明的人蓄意摧毁了这颗行星。')
p(25,'科索尼亚离泰拉如此之近，似乎至少有一名当地人在统一时代便已抵达泰拉，后来成为最早的影月苍狼之一。')
p(29,'统一战争期间，第十六军团最初的兵源，据信来自泰拉尤特里根盆地与萨姆萨提亚板下贫民窟的“猎人氏族”。这些地区生存条件恶劣，居民以冷酷、自立的性格著称。无论源于这种天性，还是帝皇为军团设计的基因模板，抑或两者共同作用，新生的第十六军团很快就在帝国早期扩张中成为突击部队的典范。他们既能以首轮攻势直接结束战斗，也能作为预备队投入，给予敌人最后一击。')
p(33,'第一次月球平定战，是第十六军团最早参与的战役之一，对其成长与成形至关重要。军团在行动中发挥决定性作用，不仅达成关键目标，也赢得赫赫声名，获称“帝皇之狼”。作为回报，他们在一段时间内获得了从被占领基因实验室征收的大部分产出，得以迅速扩充兵力；而扩编又要求更多新兵。')
p(35,'因此，据信许多早期第十六军团战士有着另一种颇为特殊的出身：他们实际上是被泰拉派出的“招募小队”，从科索尼亚绑架而来。这些小队的任务，是从遍布这个古老世界的暴力帮派中抓走数千人，再将这些“新兵”送往月球基因实验室，接受成为星际战士所需的改造与思想灌输。')
p(37,'寻回荷鲁斯后，帝皇正式赐名“影月苍狼”，以纪念军团在泰拉卫星上取得的胜利和经历的战火洗礼。尽管起源不同寻常，这些战士最终成为忠诚无比、斗志旺盛的典范。荷鲁斯接掌军团时，影月苍狼已有一万人。')
n.update({'A0554-B0002':'Horus Lupercal 与资料栏统一为荷鲁斯·卢佩卡尔；原译牧狼神荷鲁斯保留在对照中。','A0554-B0018':'战吼 Lupercal 与本篇人物姓名保持同一音译，原稿采用意译牧狼神；均指荷鲁斯的称呼，不另列为神祇。','A0554-B0021':'关于科索尼亚毁灭的时间、原因，所给英文采用推测性叙述，中文保留其不确定程度。catacombs 按行星坑道语境作地下洞窟，不强行假定全部为墓穴。'})
for fn,obj in [('edits.json',e),('notes.json',n)]:(P/fn).write_text(json.dumps(obj,ensure_ascii=False,indent=2))
(P/'partial_progress.json').write_text(json.dumps({'article':554,'read_through_block':37,'complete':False},ensure_ascii=False,indent=2))
